#!/usr/bin/env python3
"""Snapshot the compatibility surface; unknown coverage stays explicitly unknown."""
import collections, hashlib, json, re, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'okkama-rs/docs/new-runtime'
OUT.mkdir(exist_ok=True)
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def relative(path): return str(path.relative_to(ROOT))
def run(*cmd): return subprocess.check_output(cmd,cwd=ROOT,text=True).strip()
cases=[]; owners=collections.defaultdict(list); contracts=collections.defaultdict(list)
for path in sorted((ROOT/'conformance/cases').rglob('case.json')):
    c=json.loads(path.read_text());cases.append(c)
    for source in c.get('sources',[])+c.get('support',[]):
        if isinstance(source,str): owners[relative(path.parent/source)].append(c['id'])
    for ref in c.get('contracts',[]): contracts[ref['contract']].append(c['id'])
contract_defs=[]
for path in sorted((ROOT/'conformance/contracts').glob('*.json')):
    for c in json.loads(path.read_text()).get('contracts',[]):
        contract_defs.append(dict(id=c['id'],title=c.get('title'),family=c.get('family'),spec_refs=c.get('spec_refs',[]),status=c.get('status','unknown'),aspects=c.get('aspects',{}),discrepancies=c.get('discrepancies',[]),definition_source=relative(path),definition_sha256=digest(path),cases=sorted(set(contracts[c['id']]))))
text=(ROOT/'okkama-rs/crates/okkama-sparrow/src/lib.rs').read_text()
instructions=[dict(name=m[1],opcode=int(m[2]),mnemonic=m[3],operands=m[4],new_runtime='unknown',test_mapping='pending review') for m in re.finditer(r'^    (\w+) = (\d+), "([^"]+)" \{([^\n]*)\}',text,re.M)]
types=re.findall(r'^    (\w+)(?:,|\(| \{)',text.split('pub enum Type {',1)[1].split('\n}',1)[0],re.M)
abi=(ROOT/'okkama-rs/crates/okkama-runtime-abi/src/table.rs').read_text()
natives=[dict(name=m[1],id=int(m[2]),symbol=m[3],signature=m[4],new_runtime='unknown',test_mapping='pending review') for m in re.finditer(r'^    (\w+) = (\d+), "([^"]+)", "([^"]+)";',abi,re.M)]
intrinsic_source=(ROOT/'okkama-rs/crates/okkama-compiler/src/ir/mod.rs').read_text()
intrinsic_table=re.search(r'pub const INTRINSICS: \[&str; (\d+)\] = \[(.*?)\];',intrinsic_source,re.S)
intrinsics=sorted(re.findall(r'"([^"]+)"',intrinsic_table[2]))
assert len(intrinsics)==len(set(intrinsics))==int(intrinsic_table[1])
paths=sorted(set(run('git','ls-files','--cached','--others','--exclude-standard','--','*.ok').splitlines()))
programs=[]
for name in paths:
    path=ROOT/name
    if not path.is_file():continue
    source=path.read_text(errors='replace')
    has_main=bool(re.search(r'^\s*(?:async\s+)?main\s*\(',source,re.M));has_tests=bool(re.search(r'^\s*(?:async\s+)?test\s+"',source,re.M))
    category='conformance' if owners[name] else 'stdlib' if name.startswith('std/') else 'example' if name.startswith('examples/') else 'other'
    flags=[k for k,p in {'network':r'(net/|http/|web/|listen\()','database':r'"db/','process':r'(os/process|process/|spawn\s)','filesystem':r'"(fs/|io/file|os/file)','stdin':r'"io/stdin','time_or_random':r'"(time/|random/)'}.items() if re.search(p,source)]
    expectations=[dict(case=c['id'],mode=c['mode'],expect=c.get('expect'),requires=c.get('requires',{}),entry=c.get('entry')) for c in cases if c['id'] in owners[name]]
    programs.append(dict(path=name,sha256=digest(path),category=category,main=has_main,tests=has_tests,case_ids=owners[name],case_expectations=expectations,imports=re.findall(r'\bimport\s+"([^"]+)"',source),fixture_hints=flags,baseline='pending' if has_main or has_tests or owners[name] else 'dependency_or_negative_source_needs_review'))
r={'baseline_commit':run('git','rev-parse','1c289f8b'),'worktree_head':run('git','rev-parse','HEAD'),'toolchain':{'rustc':run('rustc','-Vv'),'cargo':run('cargo','-V'),'host':run('uname','-m')},'origin':json.loads((ROOT/'benchmarks/db/results/sparrow-origin.json').read_text()),'counts':{'instructions':len(instructions),'types':len(types),'natives':len(natives),'intrinsics':len(intrinsics),'contracts':len(contract_defs),'cases':len(cases),'program_files':len(programs)},'instructions':instructions,'types':types,'natives':natives,'intrinsics':[dict(symbol=s,new_runtime='unknown',test_mapping='pending review') for s in intrinsics],'contracts':contract_defs,'programs':programs}
assert r['origin']['sha256']==digest(ROOT/'sparrow-origin')
(OUT/'inventory.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
lines=['# Compatibility inventory','', 'Generated by `tools/new-runtime/inventory.py`. Pending mappings are not coverage claims.','', '| Surface | Count |','|---|---:|']+[f'| {k} | {v} |' for k,v in r['counts'].items()]
lines+=['','## Instructions','','| Opcode | Mnemonic | New runtime |','|---:|---|---|']+[f'| {i["opcode"]} | `{i["mnemonic"]}` | unknown |' for i in instructions]
lines+=['','Full native/intrinsic registry, contract-to-case links and source manifest: [inventory.json](inventory.json).','All fixture hints are discovery aids, not proof that a program is safe, runnable or deterministic.']
(OUT/'inventory.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(r['counts']))
